; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: cpcfw (Amstrad CPC - firmware text and keys), starts in normal mode
; ============================================================

			DEVICE AMSTRADCPC6128		; for SAVEAMSDOS at the end
			org #0040

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 40		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 1		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs

ntc_start:
			di
			ld (ntc_csp), sp
			ld a, (#BC77)		; Option RomEnable: start the ROMs again
			cp #DF			; AMSDOS has the cassette calls: they are running
			jr z, ntc_roms_on
			ei
			ld de, ntc_free		; the lowest address the ROMs may use (above the arrays)
			ld hl, #ABFF		; the highest (as usual for AMSDOS: it takes about #A700-#ABFF)
			ld c, 7
			call #BCCE		; KL INIT BACK: ROM 7 (DE / HL come back as the new limits)
			di
			ASSERT ntc_free <= #A600, "Option RomEnable: the program and its arrays must end below #A600 (the ROMs take their RAM from #ABFF down)"
ntc_roms_on:
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:

			; Main.bas 20: Print "Overlays on "; System.Platform; ", "; Memory.RamSize(); "K"
			dw fn_memory_ramsize, var_memory_ramsize_ramsize
			dw kw_printstrvar, str1
			dw kw_printint, var_memory_ramsize_ramsize
			dw kw_printstrvar, str2
			dw kw_printnl

			; Main.bas 22: Print "Level 1 loaded: "; Level1.Loaded()
			dw fn_level1_loaded, var_level1_loaded_loaded
			dw kw_printstrvar, str3
			dw kw_printint, var_level1_loaded_loaded
			dw kw_printnl

			; Main.bas 23: For lvl = 1 To 2
			dw kw_ltov, 1, var_lvl
for1_t:

			; Main.bas 24: If lvl = 1 Then score = score + Level1.Play(score)
			dw kw_cpeqvl, var_lvl, 1
			dw kw_goto_iffalse_n, if2_1
			dw p_level1_play_c, var_score
			dw kw_vtov, var_level1_play_play, tmp1
			dw kw_add, var_score, tmp1, var_score
if2_1:

			; Main.bas 25: If lvl = 2 Then score = score + Level2.Play(score)
			dw kw_cpeqvl, var_lvl, 2
			dw kw_goto_iffalse_n, if3_1
			dw p_level2_play_c, var_score
			dw kw_vtov, var_level2_play_play, tmp1
			dw kw_add, var_score, tmp1, var_score
if3_1:

			; Main.bas 26: Next
			dw kw_next1l_n, var_lvl, 2, for1_t
for1_e:

			; Main.bas 27: Print "Score "; score
			dw kw_printstrvar, str4
			dw kw_printint, var_score
			dw kw_printnl

			; Main.bas 29: Print "Free after level 1 "; Level1.LocalSize()
			dw fn_level1_localsize, var_level1_localsize_localsize
			dw kw_printstrvar, str5
			dw kw_printint, var_level1_localsize_localsize
			dw kw_printnl

			; Main.bas 30: Print "Free after level 2 "; Level2.LocalSize()
			dw fn_level2_localsize, var_level2_localsize_localsize
			dw kw_printstrvar, str6
			dw kw_printint, var_level2_localsize_localsize
			dw kw_printnl

			; Main.bas 31: Print "Heap, largest block "; Memory.Largest()
			dw fn_memory_largest, var_memory_largest_largest
			dw kw_printstrvar, str7
			dw kw_printint, var_memory_largest_largest
			dw kw_printnl

			; Main.bas 36: Print "Level 1 in page "; Level1.Page(); ", level 2 in page "; Level2.Page()
			dw fn_level1_page, var_level1_page_page
			dw kw_printstrvar, str8
			dw kw_printint, var_level1_page_page
			dw fn_level2_page, var_level2_page_page
			dw kw_printstrvar, str9
			dw kw_printint, var_level2_page_page
			dw kw_printnl

			; Main.bas 37: Print "Pages "; Memory.Map(1, Memory.Pages())
			dw fn_memory_pages, var_memory_pages_pages
			dw kw_vtov, var_memory_pages_pages, tmp1
			dw fn_memory_map, lit_1, tmp1, var_memory_map_map
			dw kw_printstrvar, str10
			dw kw_printstrvar, var_memory_map_map
			dw kw_printnl

			; Main.bas 38: Print "Unload level 1: "; Level1.Unload(); " - pages "; Memory.Map(1, Memory.Pages())
			dw fn_level1_unload, var_level1_unload_unload
			dw kw_printstrvar, str11
			dw kw_printint, var_level1_unload_unload
			dw kw_irq		; let interrupts in
			dw fn_memory_pages, var_memory_pages_pages
			dw kw_vtov, var_memory_pages_pages, tmp1
			dw fn_memory_map, lit_1, tmp1, var_memory_map_map
			dw kw_printstrvar, str12
			dw kw_printstrvar, var_memory_map_map
			dw kw_printnl

			; Main.bas 40: Print "Press a key";
			dw kw_printstrvar, str13

			; Main.bas 41: Do While Inkey <> 0 : Loop
do4_t:
			dw kw_inkey, tmp0
			dw kw_cpnevl, tmp0, 0
			dw kw_goto_iffalse_n, do4_e
			dw do4_t_go
do4_e:

			; Main.bas 42: Do : Frame : Loop Until Inkey <> 0
do5_t:
			dw kw_frame
			dw kw_inkey, tmp0
			dw kw_cpnevl, tmp0, 0
			dw kw_goto_iffalse_n, do5_t
do5_e:

			; Main.bas 43: Print
			dw kw_printnl

			; Main.bas 44: End
			dw kw_stop

; ============================================================
; sub banner (normal mode)
; ============================================================

p_banner:

			; Main.bas 48: Print "== "; text; " =="
			dw kw_printstrvar, str14
			dw kw_printstrvar, var_banner_text
			dw kw_printstrvar, str15
			dw kw_printnl
			dw p_banner_r

; ============================================================
; function play (normal mode)
; ============================================================


; ============================================================
; function bonus (normal mode)
; ============================================================


; ============================================================
; function play (normal mode)
; ============================================================


; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

do4_t_go:			ld sp, do4_t
			jp ntc_xn

p_banner_c:		; call banner (normal)
			pop hl			; text
			ld de, var_banner_text
			ld b, 40
p_banner_si0:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_banner_si0_e
			inc hl
			inc de
			djnz p_banner_si0
			xor a
			ld (de), a
p_banner_si0_e:
			ld (p_banner_rs), sp
			ld sp, p_banner
			jp ntc_xn
p_banner_r:		; end of banner
			ld sp, (p_banner_rs)
			jp ntc_xn
p_level1_play_c:		; call play (normal)
			pop hl			; score
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_level1_play_score), de
			ld hl, 0
			ld (var_level1_play_play), hl
			ld hl, 0
			ld (var_level1_play_i), hl
			ld (p_level1_play_rs), sp
			ld hl, ovl_blk_level1	; overlay LEVEL1.PAG
			ld de, p_level1_play_pg
			ld ix, p_level1_play_in
			jp ntc_ovl_enter
p_level1_play_in:
			ld sp, p_level1_play
			jp ntc_xn
p_level1_play_r:		; end of play
			ld sp, (ntc_csp)		; the caller's page back
			ld hl, (p_level1_play_pg)
			call mem_sel
			ld sp, (p_level1_play_rs)
			jp ntc_xn
p_level1_bonus_c:		; call bonus (normal)
			ld hl, 0
			ld (var_level1_bonus_bonus), hl
			ld (p_level1_bonus_rs), sp
			ld hl, ovl_blk_level1	; overlay LEVEL1.PAG
			ld de, p_level1_bonus_pg
			ld ix, p_level1_bonus_in
			jp ntc_ovl_enter
p_level1_bonus_in:
			ld sp, p_level1_bonus
			jp ntc_xn
p_level1_bonus_r:		; end of bonus
			ld sp, (ntc_csp)		; the caller's page back
			ld hl, (p_level1_bonus_pg)
			call mem_sel
			ld sp, (p_level1_bonus_rs)
			jp ntc_xn
p_level2_play_c:		; call play (normal)
			pop hl			; score
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_level2_play_score), de
			ld hl, 0
			ld (var_level2_play_play), hl
			ld (p_level2_play_rs), sp
			ld hl, ovl_blk_level2	; overlay LEVEL2.PAG
			ld de, p_level2_play_pg
			ld ix, p_level2_play_in
			jp ntc_ovl_enter
p_level2_play_in:
			ld sp, p_level2_play
			jp ntc_xn
p_level2_play_r:		; end of play
			ld sp, (ntc_csp)		; the caller's page back
			ld hl, (p_level2_play_pg)
			call mem_sel
			ld sp, (p_level2_play_rs)
			jp ntc_xn

; ============================================================
; Inline assembly (#asm ... #endasm)
; ============================================================

fn_level1_unload:		; function unload (asm keyword), Level1.cls line 25
			pop hl		; Level1.cls 26
			ld (ovl_kres), hl		; Level1.cls 27
			ld hl, ovl_blk_level1		; Level1.cls 28
			jp ntc_ovl_kunload		; Level1.cls 29
			ret			; end of #asm

fn_level1_loaded:		; function loaded (asm keyword), Level1.cls line 33
			pop hl		; Level1.cls 34
			ld (ovl_kres), hl		; Level1.cls 35
			ld hl, ovl_blk_level1		; Level1.cls 36
			jp ntc_ovl_kloaded		; Level1.cls 37
			ret			; end of #asm

fn_level1_page:		; function page (asm keyword), Level1.cls line 41
			pop hl		; Level1.cls 42
			ld (ovl_kres), hl		; Level1.cls 43
			ld hl, ovl_blk_level1		; Level1.cls 44
			jp ntc_ovl_kpage		; Level1.cls 45
			ret			; end of #asm

fn_level1_localsize:		; function localsize (asm keyword), Level1.cls line 58
			pop hl		; Level1.cls 59
			ld de, (#8000 - (ovl_level1_end + ovl_level1_vsize)) & #FFFE		; Level1.cls 60
			ld (hl), e		; Level1.cls 61
			inc hl		; Level1.cls 62
			ld (hl), d		; Level1.cls 63
			ret			; end of #asm

fn_level2_page:		; function page (asm keyword), Level2.cls line 37
			pop hl		; Level2.cls 38
			ld (ovl_kres), hl		; Level2.cls 39
			ld hl, ovl_blk_level2		; Level2.cls 40
			jp ntc_ovl_kpage		; Level2.cls 41
			ret			; end of #asm

fn_level2_localsize:		; function localsize (asm keyword), Level2.cls line 54
			pop hl		; Level2.cls 55
			ld de, (#8000 - (ovl_level2_end + ovl_level2_vsize)) & #FFFE		; Level2.cls 56
			ld (hl), e		; Level2.cls 57
			inc hl		; Level2.cls 58
			ld (hl), d		; Level2.cls 59
			ret			; end of #asm

fn_memory_pages:		; function pages (asm keyword), Memory.cls line 68
            pop hl		; Memory.cls 69
            ld (mem_res), hl		; Memory.cls 70
            ld hl, mem_pages		; Memory.cls 71
            jp mem_go		; Memory.cls 72
			ret			; end of #asm

fn_memory_ramsize:		; function ramsize (asm keyword), Memory.cls line 88
            pop hl		; Memory.cls 89
            ld (mem_res), hl		; Memory.cls 90
            ld hl, mem_ramsize		; Memory.cls 91
            jp mem_go		; Memory.cls 92
			ret			; end of #asm

fn_memory_map:		; function map (asm keyword), Memory.cls line 194
            pop hl		; Memory.cls 195
            ld e, (hl)		; Memory.cls 196
            inc hl		; Memory.cls 197
            ld d, (hl)		; Memory.cls 198
            ld (mem_a1), de		; Memory.cls 199
            pop hl		; Memory.cls 200
            ld e, (hl)		; Memory.cls 201
            inc hl		; Memory.cls 202
            ld d, (hl)		; Memory.cls 203
            ld (mem_a2), de		; Memory.cls 204
            pop hl		; Memory.cls 205
            ld (mem_res), hl		; Memory.cls 206
            ld hl, mem_map		; Memory.cls 207
            jp mem_go0		; Memory.cls 208
			ret			; end of #asm

fn_memory_largest:		; function largest (asm keyword), Memory.cls line 303
            pop hl		; Memory.cls 304
            ld (mem_res), hl		; Memory.cls 305
            ld hl, mem_largest		; Memory.cls 306
            jp mem_go		; Memory.cls 307
			ret			; end of #asm


